import subprocess, sys, difflib, re
wt='/home/user/fortress-landing-35b'
path=sys.argv[1]
old=subprocess.run(['git','-C',wt,'show','9d5d21bf5:'+path],capture_output=True,text=True).stdout.splitlines()
new=open(wt+'/'+path).read().splitlines()
sm=difflib.SequenceMatcher(None,old,new,autojunk=False)
for tag,i1,i2,j1,j2 in sm.get_opcodes():
    if tag=='equal': continue
    print('#### %s old %d-%d new %d-%d'%(tag,i1+1,i2,j1+1,j2))
    if tag=='replace' and (i2-i1)==(j2-j1):
        for a,b in zip(old[i1:i2],new[j1:j2]):
            aw=re.findall(r'\S+|\s+',a); bw=re.findall(r'\S+|\s+',b)
            s2=difflib.SequenceMatcher(None,aw,bw,autojunk=False)
            out=[]
            for t,x1,x2,y1,y2 in s2.get_opcodes():
                if t=='equal':
                    seg=''.join(aw[x1:x2])
                    if len(seg)>160: seg=seg[:70]+' ... '+seg[-70:]
                    out.append(seg)
                else:
                    if x2>x1: out.append('[-'+''.join(aw[x1:x2])+'-]')
                    if y2>y1: out.append('{+'+''.join(bw[y1:y2])+'+}')
            print(''.join(out)); print()
    else:
        for l in old[i1:i2]: print('OLD:',l); print()
        for l in new[j1:j2]: print('NEW:',l); print()
EOF
python3 -I wd.py explorations/coordinator/PLAN.md > plan-wd.txt; wc -c plan-wd.txt

